using Microsoft.Data.Sqlite;
using Microsoft.Extensions.Configuration;

namespace Recipes_Api.Data
{
    public static class DatabaseInitializer
    {
        public static void Initialize(IConfiguration configuration)
        {
            var connectionString = configuration.GetConnectionString("DefaultConnection")!;
            using var conn = new SqliteConnection(connectionString);
            conn.Open();

            using var cmd = conn.CreateCommand();

            // ==========================================
            // 🔹 Create schema version tracking table
            // ==========================================
            cmd.CommandText = @"
                CREATE TABLE IF NOT EXISTS __SchemaVersion (
                    Version INTEGER NOT NULL
                );";
            cmd.ExecuteNonQuery();

            // Get current schema version
            cmd.CommandText = "SELECT IFNULL(MAX(Version), 0) FROM __SchemaVersion;";
            var currentVersion = (long)cmd.ExecuteScalar()!;

            // ===========================
            // 🔸 Target version tracking
            // ===========================
            long targetVersion = 3; // increment when schema changes

            // ===================================
            // 🏗️ Version 1: Initial Schema
            // ===================================
            if (currentVersion < 1)
            {
                // Create Categories Table
                cmd.CommandText = @"
                    CREATE TABLE IF NOT EXISTS Categories (
                        Id INTEGER PRIMARY KEY AUTOINCREMENT,
                        Name TEXT NOT NULL
                    );";
                cmd.ExecuteNonQuery();

                // Seed Categories
                cmd.CommandText = "SELECT COUNT(*) FROM Categories;";
                var catCount = (long)cmd.ExecuteScalar()!;
                if (catCount == 0)
                {
                    cmd.CommandText = @"
                        INSERT INTO Categories (Name)
                        VALUES ('Breakfast'), ('Lunch'), ('Dinner'), ('Dessert'), ('Vegan');";
                    cmd.ExecuteNonQuery();
                }

                // Create Recipes Table
                cmd.CommandText = @"
                    CREATE TABLE IF NOT EXISTS Recipes (
                        Id INTEGER PRIMARY KEY AUTOINCREMENT,
                        Title TEXT,
                        ImageUrl TEXT,
                        Ingredients TEXT,
                        Instructions TEXT,
                        CookingTime TEXT,
                        CategoryId INTEGER,
                        FOREIGN KEY (CategoryId) REFERENCES Categories(Id)
                    );";
                cmd.ExecuteNonQuery();

                // Seed Recipes (placeholder URL example)
                cmd.CommandText = "SELECT COUNT(*) FROM Recipes;";
                var count = (long)cmd.ExecuteScalar()!;
                if (count == 0)
                {
                    cmd.CommandText = @"
                        INSERT INTO Recipes (Title, ImageUrl, Ingredients, Instructions, CookingTime, CategoryId)
                        VALUES
                            ('BBQ Chicken Flatbread', 'data:image/jpeg;base64,', 'Flatbread, BBQ sauce, chicken, cheese', 'Spread BBQ sauce on flatbread, top with cooked chicken and cheese, bake until crispy.', '20 min', 3),
                            ('Greek Salad', 'https://www.simplyrecipes.com/thmb/3pCkcqFdeULd0V24-eKRUeSkOh8=/750x0/filters:no_upscale():max_bytes(150000):strip_icc():format(webp)/Simply-Recipes-Easy-Greek-Salad-LEAD-2-4601eff771fd4de38f9722e8cafc897a.jpg', 'Lettuce, tomato, cucumber, feta, olives, olive oil, vinegar', 'Chop all vegetables, mix with feta and olives, drizzle with olive oil and vinegar.', '10 min', 2),
                            ('Vegan Oatmeal Bowl', 'https://example.com/oatmeal.jpg', 'Oats, almond milk, banana, chia seeds, maple syrup', 'Cook oats with almond milk, top with banana, chia seeds, and syrup.', '8 min', 5),
                            ('Chocolate Lava Cake', 'https://example.com/lavacake.jpg', 'Chocolate, flour, sugar, eggs, butter, cocoa powder', 'Mix ingredients, bake until edges set and center is molten.', '25 min', 4),
                            ('Breakfast Burrito', 'https://example.com/breakfastburrito.jpg', 'Tortilla, scrambled eggs, cheese, sausage, salsa', 'Fill tortilla, roll, and grill until golden.', '15 min', 1);";
                    cmd.ExecuteNonQuery();
                }

                // Create Favorites Table
                cmd.CommandText = @"
                    CREATE TABLE IF NOT EXISTS Favorites (
                        Id INTEGER PRIMARY KEY AUTOINCREMENT,
                        RecipeId INTEGER,
                        UserName TEXT,
                        FOREIGN KEY (RecipeId) REFERENCES Recipes(Id)
                    );";
                cmd.ExecuteNonQuery();
            }

            // ===================================
            // 🧩 Version 2: Schema / Data Changes
            // ===================================
            if (currentVersion < 2)
            {
                // Example: Add a new column
                cmd.CommandText = "ALTER TABLE Recipes ADD COLUMN NewColumnName TEXT DEFAULT NULL;";
                try { cmd.ExecuteNonQuery(); } catch { /* ignore if exists */ }

                // Example: Update image URLs
                cmd.CommandText = "UPDATE Recipes SET ImageUrl = REPLACE(ImageUrl, 'example.com', 'cdn.yoursite.com');";
                cmd.ExecuteNonQuery();
            }

            // ===================================
            // ✅ Update schema version
            // ===================================
            cmd.CommandText = "INSERT INTO __SchemaVersion (Version) VALUES (@ver);";
            cmd.Parameters.Clear();
            cmd.Parameters.AddWithValue("@ver", targetVersion);
            cmd.ExecuteNonQuery();
        }
    }
}



